const $=id=>document.getElementById(id),state={tool:'marketing',facts:defaultFacts(),images:[],designs:{marketing:defaultDesign(),sku:defaultDesign(),size:defaultDesign()},sizeCopy:{title:'',intro:'',tips:[]},skuLabels:{},plans:{},undo:{},reviews:{},briefs:{},revision:0,busy:false,loading:false,loaded:false,selectedVariant:'',selectedImage:0,request:null};
