function syncSelection(){const select=$('ecCurrentVariant'),old=state.selectedVariant;select.replaceChildren();for(const [i,v]of state.facts.variants.entries())select.add(new Option(v.name||'规格 '+(i+1),v.id));state.selectedVariant=state.facts.variants.some(v=>v.id===old)?old:state.facts.variants[0]?.id;select.value=state.selectedVariant||'';}
