function setupFields(){for(const field of document.querySelectorAll('[data-fact]')){field.value=state.facts[field.dataset.fact]??'';field.oninput=()=>{state.facts[field.dataset.fact]=field.value;invalidate();if(field.dataset.fact==='category')renderVariants();};}syncDesign();}
function syncDesign(){const design=state.designs[state.tool]||state.designs.marketing;for(const field of document.querySelectorAll('[data-design]'))field.value=design[field.dataset.design];$('ecSizeTitle').value=state.sizeCopy.title||'';$('ecSizeIntro').value=state.sizeCopy.intro||'';$('ecSizeTips').value=(state.sizeCopy.tips||[]).join('\n');}
function syncBusy(){const blocked=state.busy||state.loading||!state.loaded;for(const control of document.querySelectorAll('#ecProfileFields button,#ecProfileFields input,#ecProfileFields textarea,#ecProfileFields select,#ecEditor input,#ecEditor select,#ecEditor textarea,#ecUndo,#ecTabs button,#ecBrief,#ecCurrentVariant,#ecEmptyUpload,#ecCandidates button,#ecAuditResults select,#ecAuditResults button,#ecAuditGallery button'))control.disabled=blocked;$('ecAIStart').disabled=blocked;$('ecAIStart').textContent=state.busy?'AI 处理中…':commerceTools.find(t=>t.id===state.tool).action;$('ecAIStop').hidden=!state.busy;syncControls();}
function syncControls(){const v=currentVariant(),usable=!!state.images.length&&!!state.facts.name.trim(),blocked=state.busy||state.loading||!state.loaded;const dimensions=specLines(v,state.facts.category).some(([name])=>!/数量|件数/.test(name));
  const ready=usable&&(state.tool==='marketing'||state.tool==='sku'&&!!v?.name&&v.imageIndex!=null||state.tool==='size'&&!!v?.name&&dimensions);
  $('ecExport').disabled=blocked||!(state.tool==='audit'?!!state.plans.audit:ready);$('ecSaveLibrary').disabled=blocked||!ready||state.tool==='audit';$('ecBatch').disabled=blocked||!usable||!['sku','size'].includes(state.tool)||state.facts.variants.some(item=>!item.name||state.tool==='sku'&&item.imageIndex==null||state.tool==='size'&&!specLines(item,state.facts.category).some(([name])=>!/数量|件数/.test(name)));
  for(const id of ['ecAuditCSV','ecAuditJSON'])$(id).disabled=blocked||!state.plans.audit;
  $('ecExport').textContent=state.tool==='audit'?'下载检查表 ↗':'下载作品 ↗';$('ecBatch').hidden=!['sku','size'].includes(state.tool);$('ecSelection').hidden=!['sku','size'].includes(state.tool);$('ecMarketingFields').hidden=state.tool!=='marketing';$('ecSizeFields').hidden=state.tool!=='size';$('ecEditor').hidden=state.tool==='audit';$('ecAuditResults').hidden=state.tool!=='audit';$('ecUndo').hidden=!state.undo[state.tool];
}
function render(target=$('ecCanvas'),overrides={}){const data={tool:state.tool,facts:state.facts,images:state.images,design:state.designs[state.tool]||state.designs.marketing,variant:state.tool==='marketing'?{...currentVariant(),imageIndex:state.selectedImage}:currentVariant(),sizeCopy:state.sizeCopy,skuLabels:state.skuLabels,...overrides};if(target!==$('ecCanvas'))return renderCommerce(target,data);
  const token=++renderToken,hasImage=state.images.length>0,audit=state.tool==='audit';$('ecEmpty').hidden=hasImage;$('ecCanvas').hidden=!hasImage||audit;$('ecAuditImage').hidden=!hasImage||!audit;if(hasImage&&audit){$('ecAuditImage').src=state.images[state.selectedImage]?.url||state.images[0].url;$('ecCanvasMeta').textContent='图 '+(state.selectedImage+1)+' · 原图核对';}else if(hasImage){renderCommerce(target,data);$('ecCanvasMeta').textContent=data.design.ratio+' · '+target.width+' × '+target.height+' px';}else{const size=artworkSize(data.design);$('ecCanvasMeta').textContent=data.design.ratio+' · '+size.width+' × '+size.height+' px';}
  const missing=[];if(hasImage&&!state.facts.name.trim())missing.push('请填写商品名称');if(hasImage&&['sku','size'].includes(state.tool)&&!currentVariant()?.name)missing.push('请填写当前规格名称');if(hasImage&&state.tool==='sku'&&currentVariant()?.imageIndex==null)missing.push('请选择此规格对应的图片');if(hasImage&&state.tool==='size'&&!specLines(currentVariant(),state.facts.category).some(([name])=>!/数量|件数/.test(name)))missing.push('请补充当前规格的真实尺寸');$('ecNotice').textContent=missing.join('；');
  $('ecPreviewNote').textContent=audit?'点击核对项可定位图片；每项由人工确认。':state.tool==='size'?'示意图不代表实物比例，尺寸只取自已填资料。':'商品原图保留，文字与版式可修改。';$('ecRenderWarning').textContent=textContrast(data.design.ink,data.design.background)<4.5||textContrast(data.design.accent,data.design.background)<4.5?'文字与背景对比偏低，建议选择更深的文字或强调色。':'';syncControls();return token;
}
function renderAuditGallery(){const root=$('ecAuditGallery');root.replaceChildren();root.hidden=state.tool!=='audit'||!state.images.length;state.images.forEach((image,index)=>{const b=button('',()=>{if(state.busy)return;state.selectedImage=index;render();renderAuditGallery();});b.setAttribute('aria-pressed',String(state.selectedImage===index));const img=node('img');img.src=image.url;img.alt='';b.append(img,node('span','图 '+(index+1)+' · '+image.role));root.append(b);});}
function activate(id,push=true){if(state.busy||state.loading)return;state.tool=commerceTools.some(t=>t.id===id)?id:'marketing';const tool=commerceTools.find(t=>t.id===state.tool);$('ecTitle').firstChild?$('ecTitle').firstChild.textContent=tool.name:$('ecTitle').append(document.createTextNode(tool.name));document.title=tool.name+' · 家纺电商工具箱';for(const b of $('ecTabs').querySelectorAll('button')){if(b.dataset.tool===state.tool)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}$('ecAIStatus').textContent='';$('ecBrief').value=state.briefs[state.tool]||'';$('ecVariantsFold').open=['sku','size'].includes(state.tool);$('ecPreviewTitle').textContent=state.tool==='audit'?'商品原图':'作品预览';syncDesign();renderCandidates();renderAudit();renderAuditGallery();render();syncBusy();saveDraft();if(push)history.pushState(null,'','/ecommerce?tool='+state.tool);}
function storeUndo(id){if(state.undo[id])return;state.undo[id]={design:structuredClone(state.designs[id]),sizeCopy:structuredClone(state.sizeCopy),skuLabels:structuredClone(state.skuLabels),order:state.facts.variants.map(v=>v.id)};}
function restoreUndo(id,preserveManual=false){const previous=state.undo[id];if(!previous)return;state.designs[id]={...previous.design,...(preserveManual?previous.edited||{}:{})};if(id==='size')state.sizeCopy={...previous.sizeCopy,...(preserveManual?previous.copyEdited||{}:{})};if(id==='sku')state.skuLabels=previous.skuLabels;if(id==='sku'||id==='size')state.facts.variants.sort((a,b)=>previous.order.indexOf(a.id)-previous.order.indexOf(b.id));delete state.undo[id];if(state.plans[id])state.plans[id].applied=false;}
function adopt(index){if(state.busy)return;const result=state.plans[state.tool];if(!result||result.revision!==state.revision)return toast('资料已经变化，请重新规划');storeUndo(state.tool);const p=result.plan;if(state.tool==='marketing'){Object.assign(state.designs.marketing,p.proposals[index]);}else if(state.tool==='sku'){Object.assign(state.designs.sku,{background:p.background,accent:p.accent,ink:p.ink});state.skuLabels=Object.fromEntries(p.items.map(item=>[item.variantId,item.label]));state.facts.variants.sort((a,b)=>p.items.findIndex(item=>item.variantId===a.id)-p.items.findIndex(item=>item.variantId===b.id));}else if(state.tool==='size'){Object.assign(state.designs.size,{background:p.background,accent:p.accent,ink:p.ink});state.sizeCopy={title:p.title,intro:p.intro,tips:p.tips};state.facts.variants.sort((a,b)=>p.order.indexOf(a.id)-p.order.indexOf(b.id));}result.applied=true;syncDesign();syncSelection();renderCandidates();render();saveDraft();toast('方案已采用，可继续精修或撤回');}
function renderCandidates(){const root=$('ecCandidateList'),result=state.plans[state.tool];root.replaceChildren();$('ecCandidates').hidden=!result||state.tool==='audit';if(!result||state.tool==='audit')return;const plan=result.plan;$('ecCandidateState').textContent=result.applied?'已采用 · 可继续调整':'确认后应用';if(result.applied){root.append(node('p','已将方案用于当前作品。修改参数可继续精修，或撤回本次方案。','ec-applied'));return;}if(plan.summary)root.append(node('p',plan.summary,'ec-quiet'));
  const list=state.tool==='marketing'?plan.proposals:[plan];list.forEach((p,index)=>{const card=node('article',null,'ec-candidate');card.append(node('h3',p.name||(state.tool==='sku'?'SKU 排版方案':'尺寸导购方案')));const thumb=node('canvas');render(thumb,{design:{...state.designs[state.tool],...p,edge:480},sizeCopy:state.tool==='size'?p:state.sizeCopy,skuLabels:state.tool==='sku'?Object.fromEntries(p.items.map(item=>[item.variantId,item.label])):state.skuLabels});card.append(thumb);card.append(node('p',p.reason||p.intro||plan.items?.map(item=>item.label).join(' / ')||''));card.append(button('采用此方案',()=>adopt(index),'ec-primary'));root.append(card);});}
function renderAudit(){const root=$('ecAuditIssues');root.replaceChildren();const result=state.plans.audit;if(!result){root.append(node('p','添加商品图片与已确认资料，再点击 AI 核对。','ec-quiet'));$('ecReviewCount').textContent='';syncControls();return;}const report=result.plan;const pending=report.issues.filter(i=>!state.reviews[i.id]||state.reviews[i.id]==='pending').length;$('ecReviewCount').textContent=pending+' 项待核实';root.append(node('p',report.summary,'ec-audit-summary'));if(!report.issues.length)root.append(node('p','本次未发现明确疑点，仍需核对未确认事项。','ec-quiet'));
  const fields={pattern:'花型',craft:'工艺',quantity:'件数',size:'尺寸',text:'图文',mapping:'图片对应'};for(const issue of report.issues){const card=node('article',null,'ec-issue');card.append(node('h3',(issue.imageIndex==null?'整体':'图 '+(issue.imageIndex+1))+' · '+fields[issue.field]),node('p',issue.observation),node('p','依据：'+issue.evidence),node('p','建议：'+issue.suggestion));if(issue.imageIndex!=null)card.append(button('查看对应图片',()=>{state.selectedImage=issue.imageIndex;render();renderAuditGallery();$('ecStage').scrollIntoView({block:'nearest',behavior:'smooth'});}));const label=node('label','人工处理'),select=node('select');for(const [value,name]of [['pending','待核实'],['confirmed','确认需修改'],['dismissed','已核实无误']])select.add(new Option(name,value));select.value=state.reviews[issue.id]||'pending';select.onchange=()=>{state.reviews[issue.id]=select.value;renderAudit();saveDraft();};label.append(select);card.append(label);root.append(card);}
  const unverified=node('div',null,'ec-unverified');unverified.append(node('strong','仍需人工确认'));for(const text of report.unverified)unverified.append(node('p',text));root.append(unverified);syncControls();}
async function aiImages(){return state.images.map(image=>{const edge=768,scale=Math.min(1,edge/Math.max(image.width,image.height)),c=document.createElement('canvas');c.width=Math.round(image.width*scale);c.height=Math.round(image.height*scale);c.getContext('2d').drawImage(image.image,0,0,c.width,c.height);return c.toDataURL('image/png');});}
async function runAI(){if(state.busy||state.loading||!state.loaded)return;if(!state.facts.name.trim())return toast('请先填写商品名称');if(!state.images.length)return toast('请先添加商品图片');if(['sku','size'].includes(state.tool)&&state.facts.variants.some(v=>!v.name.trim()))return toast('请填写所有规格名称');if(state.tool==='sku'&&state.facts.variants.some(v=>v.imageIndex==null))return toast('请为每个规格选择对应图片');const controller=new AbortController(),request={controller,id:crypto.randomUUID(),revision:state.revision,tool:state.tool};state.request=request;state.busy=true;syncBusy();$('ecAIStatus').dataset.error='false';$('ecAIStatus').textContent='正在准备参考图并请求 AI…';const timer=setTimeout(()=>controller.abort('timeout'),65000);
  try{const images=await aiImages();if(state.request!==request)return;const response=await fetch('/api/textile/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'commerce-'+request.tool,images,facts:facts(),brief:$('ecBrief').value}),signal:controller.signal});let result;try{result=await response.json();}catch{throw Error('服务未返回可用内容，请检查连接后手动重试');}if(!response.ok)throw Error(result.error||'AI 请求失败（'+response.status+'）');if(state.request!==request||request.revision!==state.revision||controller.signal.aborted)return;if(result.kind!=='commerce-'+request.tool||!result.plan)throw Error('AI 结果类型不匹配，原稿已保留');state.plans[request.tool]={plan:result.plan,revision:request.revision,applied:false};if(request.tool==='audit')state.reviews={};$('ecAIStatus').textContent=request.tool==='audit'?'辅助核对完成，请逐项人工确认。':'候选已准备好，采用后才会修改作品。';renderCandidates();renderAudit();saveDraft();}
  catch(error){if(state.request===request)$('ecAIStatus').dataset.error=String(!controller.signal.aborted);if(state.request===request)$('ecAIStatus').textContent=controller.signal.aborted?(controller.signal.reason==='timeout'?'请求超时，未自动重试。':'已停止本次请求，当前作品保留。'):(error.message||'AI 请求失败，当前作品保留。');}
  finally{clearTimeout(timer);if(state.request===request){state.request=null;state.busy=false;syncBusy();}}
}
function stopAI(){const request=state.request;if(!request)return;request.controller.abort();state.request=null;state.busy=false;$('ecAIStatus').textContent='已停止本次请求，当前作品保留。';syncBusy();}
function validFacts(){const errors=localCommerceChecks(state.facts).filter(value=>!value.includes('请确认此组合'));if(errors.length)throw Error(errors[0]);for(const v of state.facts.variants)for(const [key]of dimensionFields)if(v[key]!=null&&(!Number.isFinite(v[key])||v[key]<(key==='pillowCount'?0:1)||v[key]>1000||['pieces','pillowCount'].includes(key)&&(!Number.isInteger(v[key])||v[key]>50)))throw Error('请检查规格尺寸及件数');for(const price of [state.facts.price,...state.facts.variants.map(v=>v.price)])if(price&&!/^\d{1,7}(?:\.\d{1,2})?$/.test(price))throw Error('价格请输入有效金额');}
function nameFor(suffix){return (state.facts.code||state.facts.name||'家纺商品')+'_'+suffix;}
async function download(){if($('ecExport').disabled)return;if(state.tool==='audit')return downloadAudit(false);try{validFacts();render();const suffix=state.tool==='marketing'?'营销图':currentVariant().name+'_'+(state.tool==='sku'?'SKU':'尺寸导购');saveBlob(await imageBlob($('ecCanvas')),nameFor(suffix)+'.png');}catch(e){toast(e.message);}}
async function batch(){if($('ecBatch').disabled)return;state.loading=true;syncBusy();$('ecNotice').textContent='正在逐项打包，图片不会交给 AI…';try{validFacts();const entries=[],bytes=[];let total=0;for(const [i,v]of state.facts.variants.entries()){const c=document.createElement('canvas');render(c,{variant:v});const blob=await imageBlob(c);c.width=1;c.height=1;total+=blob.size;if(total>128*1024*1024)throw Error('打包结果超过 128 MB，请降低长边尺寸或分批导出');bytes.push(blob);const safe=v.name.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_');entries.push({path:String(i+1).padStart(2,'0')+'_'+safe+'.png',item:blob});}const csv=new Blob([variantsCSV(state.facts.variants)],{type:'text/csv;charset=utf-8'});entries.push({path:'商品规格表.csv',item:csv});const zip=await buildImageArchive(entries,blob=>blob.arrayBuffer());saveBlob(zip,nameFor(state.tool==='sku'?'SKU整包':'尺寸导购整包')+'.zip');toast('已打包 '+state.facts.variants.length+' 个规格及规格表');}catch(e){toast(e.message);}finally{state.loading=false;render();syncBusy();}}
function downloadAudit(json){const result=state.plans.audit;if(!result)return;const payload=json?JSON.stringify({name:state.facts.name,created:new Date().toISOString(),scope:'AI辅助核对，需人工确认',facts:facts(),report:result.plan,reviews:state.reviews},null,2):reportCSV(result.plan,state.reviews);saveBlob(new Blob([payload],{type:json?'application/json':'text/csv;charset=utf-8'}),nameFor('核对报告')+(json?'.json':'.csv'));}
async function library(){if(state.busy||state.loading)return;const dialog=node('dialog',null,'ec-library-dialog');dialog.setAttribute('aria-label','从素材库选择商品');const head=node('h2','从我的素材库选择'),search=node('input'),grid=node('div',null,'ec-library-grid'),status=node('p','正在读取素材…','ec-quiet');search.placeholder='搜索名称、款号或系列';search.setAttribute('aria-label','搜索图库素材');dialog.append(head,search,status,grid,button('关闭',()=>dialog.close()));document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();const revision=state.revision;
  try{const {assets}=await libraryRequest();if(!Array.isArray(assets))throw Error('素材列表无效');function fill(){grid.replaceChildren();const needle=search.value.trim().toLowerCase();const filtered=assets.filter(a=>[a.name,a.code,a.collection].join(' ').toLowerCase().includes(needle));status.textContent=filtered.length?'选择原图加入当前商品。':'没有匹配素材，可上传商品图片后继续。';for(const asset of filtered.slice(0,90)){const b=button('',async()=>{if(state.revision!==revision)return toast('商品资料已变化，请重新打开素材库');b.disabled=true;try{const response=await fetch(asset.imageUrl);if(!response.ok)throw Error('素材原图读取失败');const blob=await response.blob();if(!dialog.open||state.revision!==revision)return toast('商品资料已变化或选图已取消，未覆盖当前内容');dialog.close();await addFiles([new File([blob],asset.name+'.png',{type:'image/png'})]);if(!state.facts.name){state.facts.name=asset.name;state.facts.code=asset.code||'';setupFields();invalidate();}}catch(e){status.textContent=e.message;b.disabled=false;}});const img=node('img');img.src=asset.thumbnailUrl;img.alt='';img.loading='lazy';b.append(img,node('span',asset.name),node('small',asset.code||asset.collection||'图库原图'));grid.append(b);}}search.oninput=fill;fill();}catch(e){status.textContent=e.message;}
}
async function reset(){if(state.busy||state.loading)return;const dialog=node('dialog',null,'ec-reset-dialog');dialog.setAttribute('aria-label','新建商品');dialog.append(node('h2','开始一款新商品？'),node('p','将清空本机当前商品资料、图片和 AI 候选。已下载文件和图库素材保留。'));const actions=node('div',null,'ec-dialog-actions');actions.append(button('取消',()=>dialog.close()),button('确认新建',()=>{clearTimeout(saveTimer);draftSession++;state.images.forEach(i=>URL.revokeObjectURL(i.url));Object.assign(state,{facts:defaultFacts(),images:[],designs:{marketing:defaultDesign(),sku:defaultDesign(),size:defaultDesign()},sizeCopy:{title:'',intro:'',tips:[]},skuLabels:{},plans:{},undo:{},reviews:{},briefs:{},selectedImage:0,revision:state.revision+1});setupFields();renderImages();renderVariants();activate('marketing');dialog.close();saveDraft();},'ec-primary'));dialog.append(actions);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
async function initialize(){for(const category of categories)$('ecCategory').add(new Option(category));for(const [i,t]of commerceTools.entries()){const b=button('',()=>activate(t.id));b.dataset.tool=t.id;b.append(node('small','0'+(i+1)),node('span',t.name));$('ecTabs').append(b);}setupFields();renderVariants();syncBusy();
  try{const db=await database(),saved=await new Promise((resolve,reject)=>{const tx=db.transaction('draft','readonly'),r=tx.objectStore('draft').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(saved?.version===1&&saved.facts&&Array.isArray(saved.images)&&saved.images.length<=6){const loaded=[];try{for(const item of saved.images){const decoded=await decode(item.blob,item.name);decoded.role=roles.includes(item.role)?item.role:'商品主图';loaded.push(decoded);}}catch(e){loaded.forEach(i=>URL.revokeObjectURL(i.url));throw e;}Object.assign(state,{facts:saved.facts,images:loaded,designs:saved.designs||state.designs,sizeCopy:saved.sizeCopy||state.sizeCopy,skuLabels:saved.skuLabels||{},plans:saved.plans||{},undo:saved.undo||{},briefs:saved.briefs||{},reviews:saved.reviews||{},revision:saved.revision||0,selectedVariant:saved.selectedVariant||'',selectedImage:Math.min(saved.selectedImage||0,Math.max(loaded.length-1,0))});}$('ecDraftStatus').textContent='本机草稿已就绪';}catch(e){$('ecDraftStatus').textContent='草稿暂不可用，当前页面可继续创作';}
  state.loaded=true;setupFields();renderImages();renderVariants();activate(new URLSearchParams(location.search).get('tool')||'marketing',false);
}
$('ecUpload').onclick=$('ecEmptyUpload').onclick=()=>$('ecFiles').click();$('ecFiles').onchange=event=>{addFiles(event.target.files);event.target.value='';};$('ecLibrary').onclick=library;$('ecAddVariant').onclick=()=>{if(state.facts.variants.length>=24)return toast('最多 24 个规格');state.facts.variants.push(emptyVariant());invalidate();renderVariants();};$('ecCurrentVariant').onchange=event=>{state.selectedVariant=event.target.value;render();saveDraft();};
for(const field of document.querySelectorAll('[data-design]'))field.oninput=()=>{if(state.busy)return;const design=state.designs[state.tool];if(!design)return;design[field.dataset.design]=field.dataset.design==='edge'?Number(field.value):field.value;if(state.undo[state.tool]){state.undo[state.tool].edited??={};state.undo[state.tool].edited[field.dataset.design]=design[field.dataset.design];}render();saveDraft();};
for(const [id,key]of [['ecSizeTitle','title'],['ecSizeIntro','intro'],['ecSizeTips','tips']])$(id).oninput=event=>{if(state.busy)return;state.sizeCopy[key]=key==='tips'?event.target.value.split('\n').filter(Boolean).slice(0,4):event.target.value;if(state.undo.size){state.undo.size.copyEdited??={};state.undo.size.copyEdited[key]=structuredClone(state.sizeCopy[key]);}render();saveDraft();};
$('ecBrief').oninput=()=>{state.briefs[state.tool]=$('ecBrief').value;saveDraft();};$('ecAIStart').onclick=runAI;$('ecAIStop').onclick=stopAI;$('ecUndo').onclick=()=>{restoreUndo(state.tool);syncDesign();syncSelection();renderCandidates();render();saveDraft();toast('已撤回到采用前的参数');};$('ecExport').onclick=download;$('ecBatch').onclick=batch;$('ecAuditCSV').onclick=()=>downloadAudit(false);$('ecAuditJSON').onclick=()=>downloadAudit(true);$('ecReset').onclick=reset;
$('ecSaveLibrary').onclick=async()=>{if($('ecSaveLibrary').disabled)return;state.loading=true;syncBusy();try{validFacts();const source=$('ecCanvas'),blob=await imageBlob(source);await saveAssetDialog({blob,name:nameFor(commerceTools.find(t=>t.id===state.tool).name),kind:'product',source:'家纺电商工具箱'});}catch(e){toast(e.message);}finally{state.loading=false;syncBusy();}};
$('ecDownloadCSV').onclick=()=>{try{validFacts();saveBlob(new Blob([variantsCSV(state.facts.variants)],{type:'text/csv;charset=utf-8'}),nameFor('规格表')+'.csv');}catch(e){toast(e.message);}};$('ecTemplate').onclick=()=>saveBlob(new Blob([variantsCSV([])],{type:'text/csv;charset=utf-8'}),'家纺商品规格模板.csv');$('ecImportCSV').onclick=()=>$('ecCSVFile').click();$('ecCSVFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file||state.busy||state.loading)return;const revision=state.revision;try{if(file.size>128000)throw Error('CSV 请控制在 128 KB 以内');const variants=importVariants(await file.text(),state.images.length);if(revision!==state.revision||state.busy||state.loading)throw Error('资料已变化，请重新导入规格表');state.facts.variants=variants;invalidate();renderVariants();toast('已导入 '+variants.length+' 个规格，请核对尺寸及图片对应');}catch(e){toast(e.message);}};
window.addEventListener('popstate',()=>{if(state.busy){stopAI();}activate(new URLSearchParams(location.search).get('tool')||'marketing',false);});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);if(state.loaded){const value=snapshot();saveChain=saveChain.catch(()=>{}).then(()=>storeDraft(value)).catch(()=>{});}});initialize();
